create function dao_private.settings_portfolio_republish() returns trigger
language plpgsql security definer set search_path='' as $$
declare cp public.contractor_profiles;
begin
  -- Only the owner's « save » of a published réalisation turns it into a draft.
  if old.status='published' and new.status='draft' and new.publication_consent then
    select * into cp from public.contractor_profiles where id=new.contractor_id;
    if cp.verification_status='verified' and cp.public_identity_status='approved'
       and dao_private.account_active(cp.user_id)
       and (dao_private.resolve_setting('moderation.portfolio_edit_review',cp.user_id,'contractor',null)->>'value')::boolean is false then
      new.status:='published';
    end if;
  end if;
  return new;
end;
$$;
create trigger settings_portfolio_republish before update on public.portfolio_projects
  for each row execute function dao_private.settings_portfolio_republish();
revoke all on function dao_private.settings_portfolio_republish() from public, anon, authenticated;

commit;
